import json
from itertools import permutations

def solve_puzzle():
    # Input variables based on the puzzle
    houses = [1, 2]  # Houses numbered from left (1) to right (2)
    N = len(houses)

    # Attributes and their possible values
    names = ["Arnold", "Eric"]
    lunches = ["grilled cheese", "pizza"]
    mothers_names = ["Holly", "Aniya"]

    solutions = []

    # Iterate over all permutations for each attribute category
    for names_perm in permutations(names, N):
        # Clue 2: Arnold is not in the second house (index 1)
        if names_perm[1] == "Arnold":
            continue

        for lunches_perm in permutations(lunches, N):
            # Clue 1: grilled cheese is directly left of pizza
            try:
                i_gc = lunches_perm.index("grilled cheese")
                if not (i_gc < N - 1 and lunches_perm[i_gc + 1] == "pizza"):
                    continue
            except ValueError:
                continue

            for mothers_perm in permutations(mothers_names, N):
                # Clue 3: Arnold is the person whose mother's name is Holly
                try:
                    idx_arnold = names_perm.index("Arnold")
                    if mothers_perm[idx_arnold] != "Holly":
                        continue
                except ValueError:
                    continue

                # If all constraints satisfied, record solution
                solutions.append({
                    "houses": houses[:],
                    "name": list(names_perm),
                    "lunch": list(lunches_perm),
                    "mothers' names": list(mothers_perm),
                })

    # Expect a unique solution
    if not solutions:
        raise ValueError("No solution found.")
    # If multiple solutions exist, select the first (should be unique for this puzzle)
    sol = solutions[0]

    # Prepare output in the required JSON structure
    header = ["House", "name", "lunch", "mothers' names"]
    rows = []
    for idx, h in enumerate(houses):
        rows.append([
            str(h),
            sol["name"][idx],
            sol["lunch"][idx],
            sol["mothers' names"][idx],
        ])

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
